try (ServerSocket ss = new ServerSocket(port); Socket s = ss.accept()) {
    InputStream in = s.getInputStream();
    ByteArrayOutputStream buf = new ByteArrayOutputStream();
    int b, run = 0;
    while ((b = in.read()) != -1) {
        buf.write(b);
        if (b == '\r' || b == '\n') run++; else run = 0;
        if (run == 4) break;      // \r\n\r\n 이 요청 머리의 끝이다
    }
    Files.write(Path.of("curl.bin"), buf.toByteArray());
}

